const listUnits = `-- name: ListUnits :many
SELECT id, name, system, dimension, factor FROM units
`

type ListUnitsRow struct {
	ID        int64
	Name      string
	System    string
	Dimension string
	Factor    sql.NullString
}

func (q *Queries) ListUnits(ctx context.Context) ([]ListUnitsRow, error) {
	rows, err := q.db.QueryContext(ctx, listUnits)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []ListUnitsRow
	for rows.Next() {
		var i ListUnitsRow
		if err := rows.Scan(
			&i.ID,
			&i.Name,
			&i.System,
			&i.Dimension,
			&i.Factor,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Close(); err != nil {
		return nil, err
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const lockRecipe = `-- name: LockRecipe :execrows
UPDATE recipes SET version = version WHERE id = ? AND household_id = ?
`

type LockRecipeParams struct {
	ID          int64
	HouseholdID int64
}

// LockRecipe takes the database write lock with a no-op write, so the reads
// that follow in the same transaction see the state it will change.
func (q *Queries) LockRecipe(ctx context.Context, arg LockRecipeParams) (int64, error) {
	result, err := q.db.ExecContext(ctx, lockRecipe, arg.ID, arg.HouseholdID)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected()
}

const updateRecipeDocument = `-- name: UpdateRecipeDocument :exec
UPDATE recipes
SET name = ?, description = ?, source_url = ?, author = ?,
    yield_qty = ?, yield_unit = ?, servings = ?, calories_per_serving = ?, rating = ?,
    prep_ns = ?, cook_ns = ?, total_ns = ?,
    version = version + 1, updated_at = ?, updated_by = ?
WHERE id = ? AND household_id = ?
`

type UpdateRecipeDocumentParams struct {
	Name               string
	Description        string
	SourceUrl          string
	Author             string
	YieldQty           sql.NullString
	YieldUnit          string
	Servings           sql.NullString
	CaloriesPerServing sql.NullInt64
	Rating             sql.NullInt64
	PrepNs             int64
	CookNs             int64
	TotalNs            int64
	UpdatedAt          string
	UpdatedBy          string
	ID                 int64
	HouseholdID        int64
}

func (q *Queries) UpdateRecipeDocument(ctx context.Context, arg UpdateRecipeDocumentParams) error {
	_, err := q.db.ExecContext(ctx, updateRecipeDocument,
		arg.Name,
		arg.Description,
		arg.SourceUrl,
		arg.Author,
		arg.YieldQty,
		arg.YieldUnit,
		arg.Servings,
		arg.CaloriesPerServing,
		arg.Rating,
		arg.PrepNs,
		arg.CookNs,
		arg.TotalNs,
		arg.UpdatedAt,
		arg.UpdatedBy,
		arg.ID,
		arg.HouseholdID,
	)
	return err
}
